<?php
require_once 'config.php'; require_admin();
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); $action = $_POST['action'] ?? ''; $pdo = db();
  if ($action === 'add_product') { $stmt = $pdo->prepare('INSERT INTO products (name,slug,category,short_description,description,icon,price_cents,stock,is_featured) VALUES (?,?,?,?,?,?,?,?,?)'); $stmt->execute([trim($_POST['name']),trim($_POST['slug']),trim($_POST['category']),trim($_POST['short_description']),trim($_POST['description']),trim($_POST['icon'] ?: '✦'),(int)$_POST['price_cents'],(int)$_POST['stock'],isset($_POST['is_featured']) ? 1 : 0]); flash('Ürün eklendi.'); }
  if ($action === 'delete_product') { $stmt = $pdo->prepare('UPDATE products SET is_active = 0 WHERE id = ?'); $stmt->execute([(int)$_POST['id']]); flash('Ürün vitrinden kaldırıldı.'); }
  if ($action === 'order_status') { $stmt = $pdo->prepare('UPDATE orders SET status = ? WHERE id = ?'); $stmt->execute([$_POST['status'],(int)$_POST['id']]); flash('Sipariş durumu güncellendi.'); }
  if ($action === 'feedback_status') { $stmt = $pdo->prepare('UPDATE feedback SET status = ? WHERE id = ?'); $stmt->execute([$_POST['status'],(int)$_POST['id']]); flash('Mesaj durumu güncellendi.'); }
  redirect('admin.php');
}
$products = db()->query('SELECT * FROM products ORDER BY id DESC')->fetchAll(); $orders = db()->query('SELECT * FROM orders ORDER BY created_at DESC')->fetchAll(); $feedback = db()->query('SELECT * FROM feedback ORDER BY created_at DESC')->fetchAll();
$page_title = 'Admin Paneli — Nexora'; include 'includes/header.php';
?><main class="container admin-page"><div class="section-heading"><div><span class="eyebrow">Nexora control room</span><h1>Admin paneli</h1><p>Ürün, sipariş ve geri bildirim yönetimi.</p></div><span class="pill accent">🔒 Sadece admin</span></div><section class="panel"><h2>Yeni ürün ekle</h2><form class="admin-form" method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="add_product"><input name="name" required placeholder="Ürün adı"><input name="slug" required placeholder="slug-ornek"><input name="category" required placeholder="Kategori"><input name="icon" placeholder="✦"><input name="price_cents" type="number" required placeholder="Fiyat kuruş"><input name="stock" type="number" required placeholder="Stok"><input class="wide" name="short_description" required placeholder="Kısa açıklama"><textarea class="wide" name="description" required placeholder="Detaylı açıklama"></textarea><label class="check"><input type="checkbox" name="is_featured"> Öne çıkan</label><button class="primary-btn" type="submit">Ürün ekle</button></form></section><section class="panel"><h2>Ürünler</h2><?php foreach ($products as $product): ?><div class="admin-row"><span class="product-icon"><?= e($product['icon']) ?></span><div><b><?= e($product['name']) ?></b><small><?= money((int)$product['price_cents']) ?> · stok <?= (int)$product['stock'] ?></small></div><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="delete_product"><input type="hidden" name="id" value="<?= $product['id'] ?>"><button class="remove-btn">Kaldır</button></form></div><?php endforeach; ?></section><section class="panel"><h2>Siparişler</h2><?php foreach ($orders as $order): ?><div class="admin-row"><div><b>#<?= $order['id'] ?> · <?= e($order['customer_name']) ?></b><small><?= e($order['customer_email']) ?> · <?= money((int)$order['total_cents']) ?></small></div><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="order_status"><input type="hidden" name="id" value="<?= $order['id'] ?>"><select name="status" onchange="this.form.submit()"><option value="pending" <?= $order['status']==='pending'?'selected':'' ?>>Bekliyor</option><option value="confirmed" <?= $order['status']==='confirmed'?'selected':'' ?>>Onaylandı</option><option value="fulfilled" <?= $order['status']==='fulfilled'?'selected':'' ?>>Tamamlandı</option><option value="cancelled" <?= $order['status']==='cancelled'?'selected':'' ?>>İptal</option></select></form></div><?php endforeach; if (!$orders): ?><p class="muted">Henüz sipariş yok.</p><?php endif; ?></section><section class="panel"><h2>Şikâyet ve öneriler</h2><?php foreach ($feedback as $item): ?><div class="feedback-row"><div><span class="pill accent"><?= e($item['type']) ?></span><b><?= e($item['name']) ?> · <?= e($item['email']) ?></b><p><?= nl2br(e($item['message'])) ?></p></div><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="feedback_status"><input type="hidden" name="id" value="<?= $item['id'] ?>"><select name="status" onchange="this.form.submit()"><option value="new" <?= $item['status']==='new'?'selected':'' ?>>Yeni</option><option value="read" <?= $item['status']==='read'?'selected':'' ?>>Okundu</option><option value="resolved" <?= $item['status']==='resolved'?'selected':'' ?>>Çözüldü</option></select></form></div><?php endforeach; if (!$feedback): ?><p class="muted">Henüz mesaj yok.</p><?php endif; ?></section></main><?php include 'includes/footer.php'; ?>
